result.text:
case "use-mail":
  useMail(id);
  return;
case "delete-mail": {
  const ok = await confirmDialog({
    title: "Borrar el correo",
    message: "Se quita de la lista. Las facturas que ya hayas guardado desde él no se tocan.",
    confirm: "Sí, borrar",
    danger: true,
  });
  if (!ok) return;
  deleteMessage(id);
  toast("Correo borrado.");
  render();
  return;
}
case "test-ai":
  testAi();
  return;
case "export-csv":
  exportCsv();
  return;
case "export-json":
  exportBackup();
  return;
case "import-json":
  askImportBackup();
  return;
